```js path=longestSubstring.js
/**
 * Returns the length of the longest substring without repeating characters.
 * Uses a sliding window approach with O(n) time complexity.
 * @param {string} s - The input string
 * @returns {number} Length of the longest substring without repeating characters
 */
function longestSubstring(s) {
    if (s.length === 0) return 0;

    let maxLength = 0;
    let left = 0;
    const charSet = new Set();

    for (let right = 0; right < s.length; right++) {
        const currentChar = s[right];

        // If character is already in our window, shrink from the left
        while (charSet.has(currentChar)) {
            charSet.delete(s[left]);
            left++;
        }

        // Add current character to the set
        charSet.add(currentChar);

        // Update max length if needed
        maxLength = Math.max(maxLength, right - left + 1);
    }

    return maxLength;
}

// Test cases
console.log(longestSubstring("abcabcbb")); // 3 ("abc")
console.log(longestSubstring("bbbbb"));    // 1 ("b")
console.log(longestSubstring("pwwkew"));   // 3 ("wke")
console.log(longestSubstring(""));         // 0
console.log(longestSubstring(" "));        // 1
console.log(longestSubstring("a b c"));    // 3 (spaces count as characters)
console.log(longestSubstring("aA"));       // 2 (case-sensitive)
console.log(longestSubstring("tmmzuxt"));  // 5 ("mzuxt")

// Unicode test cases
console.log(longestSubstring("😊😊"));     // 1 (duplicate emoji)
console.log(longestSubstring("a😊b"));     // 3 (emoji as a single character)
console.log(longestSubstring("e\u0301"));  // 1 (e + combining acute accent)
console.log(longestSubstring("e\u0301a")); // 2 (e + combining acute + a)
```

Now, let me explain the Unicode handling:

### Unicode Handling Explanation

#### 1. UTF-16 Code Units vs. Unicode Code Points vs. Grapheme Clusters

**UTF-16 Code Units:**
- JavaScript strings are UTF-16 encoded
- Each character is represented by 1 or 2 code units (16-bit values)
- Characters outside the Basic Multilingual Plane (BMP) require 2 code units (surrogate pairs)
- String indexing (s[0], s.length) operates on code units
- Example: "😊" is represented by 2 code units: "\uD83D\uDE0A"

**Unicode Code Points:**
- The actual numeric value assigned to a character in the Unicode standard
- Range from 0 to 0x10FFFF
- Can be represented in JavaScript with `\u{XXXX}` notation
- Example: "😊" has code point U+1F60A

**User-Perceived Grapheme Clusters:**
- How characters appear to users (what they perceive as a single "character")
- Can consist of multiple Unicode code points
- Examples:
  - "é" can be a single code point (U+00E9) or e + combining acute accent (e + U+0301)
  - Flags like 🇺🇸 are composed of regional indicator symbols (U+1F1FA U+1F1F8)
  - Emoji with skin tones or modifiers (e.g., 👨‍👩‍👧‍👦)

#### 2. Supporting User-Perceived Characters

To properly handle grapheme clusters:

```js path=graphemeAwareSubstring.js
/**
 * Grapheme-aware version of longest substring without repeating characters
 * @param {string} s - The input string
 * @returns {number} Length of the longest substring without repeating characters
 */
function longestSubstringGraphemeAware(s) {
    if (s.length === 0) return 0;

    // Check for Intl.Segmenter support
    if (!Intl.Segmenter) {
        console.warn("Intl.Segmenter not supported. Falling back to code point counting.");
        return longestSubstring(s);
    }

    const segmenter = new Intl.Segmenter(undefined, { granularity: 'grapheme' });
    const segments = segmenter.segment(s);
    const graphemes = Array.from(segments).map(s => s.segment);

    let maxLength = 0;
    let left = 0;
    const graphemeSet = new Set();

    for (let right = 0; right < graphemes.length; right++) {
        const currentGrapheme = graphemes[right];

        // If grapheme is already in our window, shrink from the left
        while (graphemeSet.has(currentGrapheme)) {
            graphemeSet.delete(graphemes[left]);
            left++;
        }

        // Add current grapheme to the set
        graphemeSet.add(currentGrapheme);

        // Update max length if needed
        maxLength = Math.max(maxLength, right - left + 1);
    }

    return maxLength;
}

// Test grapheme-aware version
console.log(longestSubstringGraphemeAware("e\u0301a")); // Should be 2, not 1
console.log(longestSubstringGraphemeAware("👨‍👩‍👧‍👦👨‍👩‍👧‍👦")); // Should be 1, not 2
```

**Runtime Support Policy:**
1. Use `Intl.Segmenter` when available (modern browsers, Node.js 16+)
2. Fall back to code point counting when not available
3. Document the limitation in environments without `Intl.Segmenter`
4. Consider using a polyfill for broader compatibility if needed

#### 3. Why Brute-Force and Optimized Must Measure Lengths in Same Unit

When comparing implementations:
- If brute-force counts grapheme clusters but optimized counts code points, the results won't be comparable
- Example: "e\u0301" would be length 2 in brute-force but length 1 in code-point optimized
- Consistency ensures:
  1. Fair comparison of algorithm efficiency
  2. Correct validation of test cases
  3. Accurate measurement of actual user-perceived character counts

### Complexity Analysis

- **Time Complexity**: O(n) - We traverse the string once with the sliding window
- **Space Complexity**: O(min(n, m)) - Where m is the size of the character set (alphabet size). In the worst case, we store all unique characters in the window.

